html:
{%- set v = invoice_context(doc) -%}
{%- set cur = doc.currency -%}
<style>
	/* paper size comes from the thermal printer driver (roll width); Chrome ignores "auto" heights */
	@page { margin: 2mm 3mm; }
	.print-format { padding: 0 !important; margin: 0 !important; max-width: 74mm !important; width: 74mm !important; min-height: 0 !important; }
	.rr { font-family: Arial, Helvetica, sans-serif; font-size: 9pt; color: #000; width: 74mm; line-height: 1.25; }
	.rr table { width: 100%; border-collapse: collapse; }
	.rr td { padding: 1px 0 !important; vertical-align: top; border: 0 !important; }
	.rr .c { text-align: center; }
	.rr .r { text-align: right; }
	.rr .b { font-weight: 700; }
	.rr .sm { font-size: 7.5pt; }
	.rr .hr { border-top: 1px dashed #000; margin: 3px 0; }
	.rr .big { font-size: 13pt; font-weight: 700; }
	.rr .name { font-size: 12pt; font-weight: 700; }
	.rr .hsn td { font-size: 7.5pt; }
</style>
<div class="rr">
	<div class="c name">{{ v.company.name }}</div>
	<div class="c sm">{{ v.company.address }}</div>
	{%- if v.company.phone %}<div class="c sm">{{ _("Ph") }}: {{ v.company.phone }}</div>{% endif %}
	{%- if v.company.gstin and not v.company.gstin_in_address %}<div class="c sm">GSTIN: {{ v.company.gstin }}</div>{% endif %}
	<div class="hr"></div>
	<div class="c b">{{ _(v.title) | upper }}</div>
	<table class="sm">
		<tr><td>{{ _("Bill") }}: <b>{{ doc.name }}</b></td><td class="r">{{ frappe.utils.format_date(doc.posting_date) }} {{ v.time }}</td></tr>
		{%- if doc.is_return and doc.return_against %}<tr><td colspan="2">{{ _("Against") }}: {{ doc.return_against }}</td></tr>{% endif %}
		{%- if not v.customer.walk_in %}<tr><td colspan="2">{{ _("Customer") }}: {{ v.customer.name }}{% if v.customer.mobile %} ({{ v.customer.mobile }}){% endif %}</td></tr>{% endif %}
		{%- if v.customer.gstin %}<tr><td colspan="2">GSTIN: {{ v.customer.gstin }}</td></tr>{% endif %}
	</table>
	<div class="hr"></div>
	<table>
		{%- for i in v.lines %}
		<tr><td colspan="2" class="b">{{ i.item_name }}{% if i.details %} <span class="sm">({{ i.details }})</span>{% endif %}</td></tr>
		{%- if i.serials %}<tr><td colspan="2" class="sm">{{ _("S/N") }}: {{ i.serials | join(", ") }}</td></tr>{% endif %}
		<tr class="sm"><td>{{ i.qty | int if i.qty == i.qty|int else i.qty }} x {{ frappe.utils.fmt_money(i.rate, currency=cur) }}{% if i.hsn %} &nbsp; HSN {{ i.hsn }}{% endif %}</td>
			<td class="r b">{{ frappe.utils.fmt_money(i.amount, currency=cur) }}</td></tr>
		{%- if i.discount %}<tr class="sm"><td>{{ _("Discount") }}</td><td class="r">-{{ frappe.utils.fmt_money(i.discount, currency=cur) }}</td></tr>{% endif %}
		{%- endfor %}
	</table>
	<div class="hr"></div>
	<table>
		<tr class="sm"><td>{{ _("Items") }}: {{ v.lines | length }} &nbsp; {{ _("Qty") }}: {{ v.total_qty | int if v.total_qty == v.total_qty|int else v.total_qty }}</td>
			<td class="r">{{ frappe.utils.fmt_money(v.total, currency=cur) }}</td></tr>
		{%- for t in v.taxes %}<tr class="sm"><td>{{ t.description }}{% if v.tax_inclusive %} ({{ _("incl.") }}){% endif %}</td><td class="r">{{ frappe.utils.fmt_money(t.amount, currency=cur) }}</td></tr>{% endfor %}
		{%- if v.discount %}<tr class="sm"><td>{{ _("Discount") }}</td><td class="r">-{{ frappe.utils.fmt_money(v.discount, currency=cur) }}</td></tr>{% endif %}
		{%- if v.rounding %}<tr class="sm"><td>{{ _("Rounding") }}</td><td class="r">{{ frappe.utils.fmt_money(v.rounding, currency=cur) }}</td></tr>{% endif %}
		<tr><td class="big">{{ _("TOTAL") }}</td><td class="r big">{{ frappe.utils.fmt_money(v.grand_total, currency=cur) }}</td></tr>
		{%- for p in v.payments %}<tr class="sm"><td>{{ p.mode }}</td><td class="r">{{ frappe.utils.fmt_money(p.amount, currency=cur) }}</td></tr>{% endfor %}
		{%- if v.change %}<tr class="sm"><td>{{ _("Change") }}</td><td class="r">{{ frappe.utils.fmt_money(v.change, currency=cur) }}</td></tr>{% endif %}
	</table>
	{%- if v.hsn.kinds %}
	<div class="hr"></div>
	<table class="hsn">
		<tr class="b"><td>HSN</td><td class="r">{{ _("Taxable") }}</td>{% for k in v.hsn.kinds %}<td class="r">{{ k }}</td>{% endfor %}</tr>
		{%- for h in v.hsn.rows %}
		<tr><td>{{ h.hsn or "-" }}</td><td class="r">{{ "%.2f" | format(h.taxable) }}</td>
			{%- for k in v.hsn.kinds %}{% set t = h.taxes.get(k) %}<td class="r">{% if t %}{{ "%.2f" | format(t.amount) }}<br>@{{ t.rate | round(2) }}%{% else %}-{% endif %}</td>{% endfor %}</tr>
		{%- endfor %}
	</table>
	{%- endif %}
	{%- if v.in_words %}<div class="sm" style="margin-top:3px">{{ v.in_words }}</div>{% endif %}
	{%- if v.loyalty_points %}<div class="sm">{{ _("Loyalty points used") }}: {{ v.loyalty_points }}</div>{% endif %}
	<div class="hr"></div>
	{%- if doc.terms %}<div class="sm">{{ doc.terms }}</div>{% endif %}
	<div class="c">{{ _("Thank you! Visit again.") }}</div>
</div>
